/* ===========================================================================
 | قالب‌های کلی (overall) هر تست روانشناسی — سطح ویژه
 * =========================================================================*/
function fr_mi_overall(): string
{
    return '<p>تست روانشناسی هوش‌های چندگانهٔ گاردنر نشان می‌دهد که ذهن شما یک «سیستم توزیع‌شده» است: هر ۹ هوش در شما وجود دارد اما با شدت متفاوت فعال می‌شود. این گزارش بر مبنای نظریهٔ هوارد گاردنر (۱۹۸۳) و پرسش‌نامهٔ هنجارشدهٔ مک‌کنزی تنظیم شده است؛ از آنجایی که خودگزارشی است، تصویرِ «شیفتگیِ خودانگاشتهٔ» شما را از قوه‌هایتان می‌سازد — نه تست روانشناسیِ عملکردیِ صرف.</p>
<p><b>خوانش کلی پروفایل:</b> مقایسهٔ ۹ نمرهٔ شما می‌گوید مغزتان بیش از جهتِ دیگر به چه کانال‌هایی پاسخ می‌دهد؛ کانال‌های بالاردهٔ شما بهترین راه‌های یادگیری و کسب‌وکارِ طبیعی‌تان را می‌سازند و چند پایین‌ترین، از طریق تمرین و تلفیق با قوه‌های اصلی، قابل رشدند. گاردنر خودش تأکید می‌کرد که ترکیبِ هوش‌ها مهم‌تر از بزرگیِ هر کدام است.</p>
<p><b>نکتهٔ بافت‌محور:</b> در فضای آموزش و کار ایران که عمدتاً دو هوش — زبانی و منطقی — را جدی می‌گیرد، به‌رسمیت‌شناختنِ ۷ کانالِ دیگر، راهِ کشفِ ظرفیت‌های پنهانِ شخصی و خانوادگی است. والدین می‌توانند از همین قالب برای فهمِ شیوهٔ یادگیریِ فرزندانشان استفاده کنند.</p>';
}

function fr_eq_overall(): string
{
    return '<p>نمرهٔ کلی هوش هیجانی شما (از ۳۳ تا ۱۶۵) ترکیبی از چهار توانمندی است: خواندن هیجان، مدیریت آن در خود، مدیریتِ آن در روابط، و به‌کارگرفتنش در خدمتِ اهداف. این ابزار بر اساس مقیاس خودگزارشی شوت (SSEIT — Schutte و همکاران، ۱۹۹۸) ساخته شده، از معتبرترین ابزارهای سنجش هوش هیجانیِ به‌کاررفته در پژوهش‌های ایرانی است.</p>
<p><b>چرا هوش هیجانی مهم است؟</b> پژوهش‌های فراوان نشان داده‌اند هوش هیجانی با رضایت از روابط، عملکرد شغلی (به‌ویژه در مشاغل رابطه‌محور ایران)، سلامت روان و حتی سرسختیِ مدیریتی ارتباط معنادار دارد — و به‌جای ثابت بودن، در سراسر زندگی تمرینی و قابل‌رشد است.</p>
<p><b>خوانش کلی:</b> نمرهٔ کلی حدودِ توانمندیِ عمومی شماست؛ اما تصویرِ واقعی در جزئیاتِ هر چهار عامل است. تعادلی که به کدام سمتش بیشتر وزن بگذارید، معمولاً مسیرِ رشدِ شخصی‌تان را هم مشخص می‌کند.</p>';
}
